pub fn brew(names: &[&str]) -> String {
    if names.is_empty() {
        return report::render(&[]);
    }
    let valid: Vec<&str> = names
        .iter()
        .copied()
        .filter(|name| recipe::portions(name) > 0)
        .collect();
    report::render(&valid)
}

pub fn retry(attempts: i32) -> i32 {
    if attempts <= 0 {
        return 0;
    }
    1 + retry(attempts - 1)
}

pub fn score(batches: &[Vec<&str>]) -> i32 {
    let mut result = 0;
    for batch in batches {
        for name in batch {
            let count = recipe::portions(name);
            if count > 0 && count <= 3 {
                result += count;
            }
        }
    }
    result
}

pub fn classify(amount: i32) -> i32 {
    match amount {
        i32::MIN..=0 => 0,
        1..=3 => 1,
        4..=8 => 2,
        _ => 3,
    }
}

pub fn ready(water: i32, beans: i32, cups: i32, temperature: i32) -> bool {
    water > 0 && beans > 0 && cups > 0 && temperature >= 90 && temperature <= 96
}

pub fn route(active: bool, amount: i32) -> &'static str {
    if active {
        if amount > 8 {
            return "courier";
        } else if amount > 3 {
            return "table";
        } else if amount > 0 {
            return "counter";
        }
    }
    "hold"
}

